using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace CFEditor {
sealed class FakeAssetLease:IAssetPortLease {
 public readonly int ThreadID=Thread.CurrentThread.ManagedThreadId;public int Released;
 public void Dispose(){if(Thread.CurrentThread.ManagedThreadId!=ThreadID||Interlocked.Increment(ref Released)!=1)throw new Exception("Lease released outside its owner or more than once");}
}
sealed class FakeAssetPortDriver:IAssetPortDriver {
 readonly object sync=new object();readonly List<AssetMidiBuffer> queued=new List<AssetMidiBuffer>();public readonly List<AssetMidiBuffer> Buffers=new List<AssetMidiBuffer>();public readonly List<bool> Directions=new List<bool>();public readonly List<byte[]> Sent=new List<byte[]>();
 public int OwnerThread,Calls,CloseCalls;public volatile bool HoldOutput,BlockUnprepare,FailRevalidate,FailQueue,FailSend;public Action<byte[]> Respond;public AssetMidiBuffer LastOutput;public readonly ManualResetEvent OpenGate=new ManualResetEvent(true);public volatile bool EnteredOpen;
 void Check(){int id=Thread.CurrentThread.ManagedThreadId;if(OwnerThread==0)OwnerThread=id;if(id!=OwnerThread)throw new Exception("Driver called outside its worker");Calls++;}
 static int FlagsOffset{get{return Marshal.OffsetOf(typeof(AssetMidiHeader),"Flags").ToInt32();}}static int RecordedOffset{get{return Marshal.OffsetOf(typeof(AssetMidiHeader),"Recorded").ToInt32();}}
 static void Flags(AssetMidiBuffer b,uint flags){Marshal.WriteInt32(b.Header,FlagsOffset,(int)flags);}
 static void Complete(AssetMidiBuffer b,byte[] data){if(data!=null)Marshal.Copy(data,0,b.Data,data.Length);Marshal.WriteInt32(b.Header,RecordedOffset,data==null?0:data.Length);Thread.MemoryBarrier();Flags(b,3);}
 public uint OpenInput(uint index,out IntPtr handle){Check();EnteredOpen=true;OpenGate.WaitOne();if(index!=4)throw new Exception("Input index changed");handle=new IntPtr(111);return 0;}
 public uint OpenOutput(uint index,out IntPtr handle){Check();if(index!=9)throw new Exception("Output index changed");handle=new IntPtr(222);return 0;}
 public void Revalidate(AssetPortBinding binding,bool input,IntPtr handle){Check();if(FailRevalidate)throw new IOException("Synthetic hotplug identity mismatch");}
 public uint Prepare(bool input,IntPtr h,AssetMidiBuffer b){Check();lock(sync){Buffers.Add(b);Directions.Add(input);}Flags(b,2);return 0;}
 public uint Unprepare(bool input,IntPtr h,AssetMidiBuffer b){Check();if(BlockUnprepare)return 65;lock(sync)queued.Remove(b);Flags(b,0);return 0;}
 public uint QueueInput(IntPtr h,AssetMidiBuffer b){Check();if(FailQueue)return 4;lock(sync){Marshal.WriteInt32(b.Header,RecordedOffset,0);Flags(b,6);queued.Add(b);}return 0;}
 public uint StartInput(IntPtr h){Check();return 0;}public uint StopInput(IntPtr h){Check();return 0;}
 public uint Reset(bool input,IntPtr h){Check();lock(sync){for(int i=0;i<Buffers.Count;i++)if(Directions[i]==input&&!Buffers[i].Released)Complete(Buffers[i],null);queued.Clear();}return 0;}
 public uint Close(bool input,IntPtr h){Check();if(h!=new IntPtr(input?111:222))throw new Exception("Foreign handle closed");Interlocked.Increment(ref CloseCalls);return 0;}
 public uint Send(IntPtr h,AssetMidiBuffer b){Check();LastOutput=b;var bytes=new byte[b.Capacity];Marshal.Copy(b.Data,bytes,0,bytes.Length);lock(sync)Sent.Add(bytes);if(FailSend)return 4;var respond=Respond;if(respond!=null)respond(bytes);if(HoldOutput)Flags(b,6);else Complete(b,null);return 0;}
 public bool Deliver(byte[] bytes){lock(sync){if(queued.Count==0)return false;var b=queued[0];queued.RemoveAt(0);Complete(b,bytes);return true;}}
 public void CompleteOutput(){lock(sync){if(LastOutput!=null&&!LastOutput.Released)Complete(LastOutput,null);}}
 public void InvalidHeader(){lock(sync){var b=queued[0];queued.RemoveAt(0);Marshal.WriteInt32(b.Header,RecordedOffset,b.Capacity+1);Flags(b,3);}}
}
static class AssetPortOwnerChecks {
 static void Need(bool value,string text){if(!value)throw new Exception(text);}
 static async Task Until(Func<bool> value){var until=DateTime.UtcNow.AddSeconds(5);while(!value()){if(DateTime.UtcNow>until)throw new Exception("Synthetic owner timed out");await Task.Delay(5).ConfigureAwait(false);}}
 static async Task Refuse(Task task){try{await task.ConfigureAwait(false);}catch(IOException){return;}catch(OperationCanceledException){return;}throw new Exception("Invalid operation reported success");}
 static AssetPortBinding Binding(){return AssetPortBinding.Select(2424833,new[]{new AssetMidiEndpoint(4,true,"Catalyst",@"\\?\synthetic-input",@"USB\VID_0E41&PID_0001\SYNTHETIC",true),new AssetMidiEndpoint(9,false,"Catalyst",@"\\?\synthetic-output",@"USB\VID_0E41&PID_0001\SYNTHETIC",true)});}
 static async Task<List<string>> Checks(){
  Need(IntPtr.Size==4&&Marshal.SizeOf(typeof(AssetMidiHeader))==64&&Marshal.OffsetOf(typeof(AssetMidiHeader),"Flags").ToInt32()==16,"MIDIHDR x86 ABI mismatch");
  var checks=new List<string>();var d=new FakeAssetPortDriver();FakeAssetLease lease=null;var owner=await AssetPortOwner.Open(Binding(),d,()=>lease=new FakeAssetLease()).ConfigureAwait(false);var received=new List<byte[]>();owner.BytesReceived+=b=>{lock(received)received.Add(b);};
  byte[] packet=AssetWire.Encode(new AssetMessage{Product=2424833,Opcode=1,Transaction=9});await owner.Send(packet,CancellationToken.None).ConfigureAwait(false);Need(d.Sent.Count==1&&d.Sent[0].SequenceEqual(packet),"Send data changed");
  Need(d.Deliver(new byte[]{0xf0,0x7d})&&d.Deliver(new byte[]{1,2,0xf7}),"No input buffers");await Until(()=>{lock(received)return received.Count==2;});Need(received[0].SequenceEqual(new byte[]{0xf0,0x7d})&&received[1].SequenceEqual(new byte[]{1,2,0xf7}),"Receive ordering changed");
  await owner.CloseAsync().ConfigureAwait(false);Need(owner.Closed&&d.Buffers.All(b=>b.Released)&&lease.Released==1&&d.CloseCalls==2&&d.OwnerThread==lease.ThreadID,"Normal ownership cleanup failed");checks.Add("One owner thread, ordered fragments, exact send, both owned handles closed and every unprepared buffer freed once");
  d=new FakeAssetPortDriver();var responder=d;d.Respond=bytes=>{
   var request=AssetWire.Decode(bytes);var data=new byte[20];Buffer.BlockCopy(BitConverter.GetBytes(1u),0,data,4,4);Buffer.BlockCopy(BitConverter.GetBytes(256u),0,data,8,4);Buffer.BlockCopy(BitConverter.GetBytes(5u),0,data,12,4);Buffer.BlockCopy(BitConverter.GetBytes(2u),0,data,16,4);
   var reply=AssetWire.Encode(new AssetMessage{Product=request.Product,Opcode=(byte)(request.Opcode|64),Session=request.Transaction,Transaction=request.Transaction,Slot=request.Slot,Number=request.Number,Data=data});
   Need(responder.Deliver(reply.Take(7).ToArray())&&responder.Deliver(reply.Skip(7).ToArray()),"Synthetic receive queue exhausted");
  };owner=await AssetPortOwner.Open(Binding(),d,()=>new FakeAssetLease()).ConfigureAwait(false);
  using(var exchange=new AssetMidiExchange(owner))for(uint tx=10;tx<30;tx++){
   var request=new AssetMessage{Product=2424833,Opcode=1,Transaction=tx};var reply=AssetWire.Decode(await exchange.Exchange(AssetWire.Encode(request),2000,CancellationToken.None).ConfigureAwait(false));Need(AssetWire.RepliesTo(request,reply),"Fragmented owner reply mismatch");
  }await owner.CloseAsync().ConfigureAwait(false);checks.Add("Twenty fragmented real codec exchanges retain FIFO order across repeated input-header wraparound");
  d=new FakeAssetPortDriver{HoldOutput=true};lease=null;owner=await AssetPortOwner.Open(Binding(),d,()=>lease=new FakeAssetLease()).ConfigureAwait(false);var sent=owner.Send(packet,CancellationToken.None);await Until(()=>d.LastOutput!=null);Need(!sent.IsCompleted&&!d.LastOutput.Released,"Output released before driver completion");await Refuse(owner.Send(packet,CancellationToken.None));d.CompleteOutput();await sent.ConfigureAwait(false);await owner.CloseAsync().ConfigureAwait(false);Need(lease.Released==1,"Concurrent-send cleanup failed");checks.Add("An in-flight SysEx retains its buffer and prevents overlapping output");
  d=new FakeAssetPortDriver();owner=await AssetPortOwner.Open(Binding(),d,()=>new FakeAssetLease()).ConfigureAwait(false);using(var cancel=new CancellationTokenSource()){cancel.Cancel();await Refuse(owner.Send(packet,cancel.Token));}await owner.Send(packet,CancellationToken.None).ConfigureAwait(false);await owner.CloseAsync().ConfigureAwait(false);checks.Add("Cancellation before queueing performs no send and leaves the channel usable");
  d=new FakeAssetPortDriver{HoldOutput=true};owner=await AssetPortOwner.Open(Binding(),d,()=>new FakeAssetLease()).ConfigureAwait(false);using(var cancel=new CancellationTokenSource()){sent=owner.Send(packet,cancel.Token);await Until(()=>d.LastOutput!=null);cancel.Cancel();await Refuse(sent);Need(!d.LastOutput.Released,"Cancelled native output freed while owned");}await owner.CloseAsync().ConfigureAwait(false);Need(d.Buffers.All(b=>b.Released),"Cancelled output not freed after return");checks.Add("Cancellation in flight retains native memory until reset/unprepare of its own handle");
  d=new FakeAssetPortDriver{FailSend=true};owner=await AssetPortOwner.Open(Binding(),d,()=>new FakeAssetLease()).ConfigureAwait(false);await Refuse(owner.Send(packet,CancellationToken.None));Need(!d.LastOutput.Released,"Failed send discarded prepared memory");await owner.CloseAsync().ConfigureAwait(false);checks.Add("A driver send error does not free a prepared header prematurely");
  d=new FakeAssetPortDriver();lease=null;owner=await AssetPortOwner.Open(Binding(),d,()=>lease=new FakeAssetLease()).ConfigureAwait(false);d.BlockUnprepare=true;await Refuse(owner.CloseAsync());Need(owner.Quarantined&&!owner.Closed&&lease.Released==0&&d.CloseCalls==0&&d.Buffers.All(b=>!b.Released),"Quarantine released driver-owned memory or lease");d.BlockUnprepare=false;await owner.CloseAsync().ConfigureAwait(false);Need(owner.Closed&&!owner.Quarantined&&lease.Released==1,"Explicit close retry did not recover");checks.Add("STILLPLAYING quarantines pointers and the lease; an explicit successful retry releases them");
  d=new FakeAssetPortDriver{FailRevalidate=true};lease=null;await Refuse(AssetPortOwner.Open(Binding(),d,()=>lease=new FakeAssetLease()));await Until(()=>lease!=null&&lease.Released==1);Need(d.Buffers.Count==0&&d.CloseCalls==1,"Changed identity opened/prepared another port");checks.Add("Identity change after open is refused before output or SysEx preparation");
  d=new FakeAssetPortDriver{FailQueue=true};lease=null;await Refuse(AssetPortOwner.Open(Binding(),d,()=>lease=new FakeAssetLease()));await Until(()=>lease!=null&&lease.Released==1);Need(d.Buffers.All(b=>b.Released)&&d.CloseCalls==2,"Partial-open buffers leaked");checks.Add("Partial initialization closes only its handles and unprepares allocated headers");
  d=new FakeAssetPortDriver();lease=null;d.OpenGate.Reset();await Refuse(AssetPortOwner.Open(Binding(),d,()=>lease=new FakeAssetLease(),30));Need(d.EnteredOpen&&lease.Released==0,"Blocked driver lost its lease");d.OpenGate.Set();await Until(()=>lease.Released==1);Need(d.CloseCalls==1&&d.Buffers.Count==0,"Timed-out open continued opening ports");checks.Add("A blocked open has a deadline, keeps ownership, then closes its input without opening output when it returns");
  d=new FakeAssetPortDriver();owner=await AssetPortOwner.Open(Binding(),d,()=>new FakeAssetLease()).ConfigureAwait(false);var failed=new TaskCompletionSource<bool>();owner.Failed+=e=>failed.TrySetResult(true);d.InvalidHeader();await Until(()=>failed.Task.IsCompleted);await owner.CloseAsync().ConfigureAwait(false);Need(d.Buffers.All(b=>b.Released),"Malformed-header cleanup failed");checks.Add("Invalid recorded lengths fail closed without copying beyond a buffer");return checks;
 }
 public static int Run(string file){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(file)));try{var checks=Checks().GetAwaiter().GetResult();File.WriteAllText(file,new JavaScriptSerializer().Serialize(new{passed=true,USB_opened=false,SDK_loaded=false,device_enumeration=false,native_driver_called=false,MIDIHDR_bytes=64,checks}));return 0;}catch(Exception e){File.WriteAllText(file,new JavaScriptSerializer().Serialize(new{passed=false,USB_opened=false,error=e.ToString()}));return 1;}}
}
}
